using System.Collections.Immutable;
using System.Data;
using System.Security.Cryptography;
using System.Text.Json;
using Microsoft.Extensions.Options;
using Npgsql;
using NpgsqlTypes;
using Platform.SoftwareFactory.Delivery;
using Platform.SoftwareFactory.InternalService;

namespace Platform.SoftwareFactory.Persistence;

internal static class TestsDb
{
    internal static void Add(NpgsqlCommand c,string n,NpgsqlDbType t,object v)=>c.Parameters.Add(new NpgsqlParameter(n,t){Value=v});
    internal static string Digest<T>(T value)=>Convert.ToHexStringLower(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(value)));
}

public sealed class PostgreSqlTestsSandboxReceiptReader(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):ITestsSandboxExecutionReceiptReader
{
    public async Task<GovernedSandboxExecutionReceipt?> LoadAsync(Guid id,string tenant,string purpose,Guid security,Guid generation,Guid run,string candidate,string securityDigest,string resultDigest,string evidence,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new TestsDependencyUnavailableException("Sandbox evidence not configured.");const string sql="SELECT record_json,record_sha256_digest,evidence_reference,evidence_references,recorded_at FROM software_factory.sandbox_evidence WHERE tenant_id=@tenant AND execution_id=@id AND security_validation_id=@security AND generation_id=@generation AND delivery_run_id=@run AND candidate_sha256_digest=@candidate AND security_report_sha256_digest=@security_digest AND result_sha256_digest=@result AND evidence_reference=@evidence";try{await using var cn=await data.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand(sql,cn){CommandTimeout=o.CommandTimeoutSeconds};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,tenant);TestsDb.Add(cmd,"id",NpgsqlDbType.Uuid,id);TestsDb.Add(cmd,"security",NpgsqlDbType.Uuid,security);TestsDb.Add(cmd,"generation",NpgsqlDbType.Uuid,generation);TestsDb.Add(cmd,"run",NpgsqlDbType.Uuid,run);TestsDb.Add(cmd,"candidate",NpgsqlDbType.Text,candidate);TestsDb.Add(cmd,"security_digest",NpgsqlDbType.Text,securityDigest);TestsDb.Add(cmd,"result",NpgsqlDbType.Text,resultDigest);TestsDb.Add(cmd,"evidence",NpgsqlDbType.Text,evidence);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;var record=JsonSerializer.Deserialize<SandboxEvidenceRecord>(r.GetString(0))??throw new InvalidOperationException();var digest=TestsDb.Digest(record);if(record.ExecutionId!=id||record.SecurityValidationId!=security||record.GenerationId!=generation||record.DeliveryRunId!=run||record.TenantId!=tenant||record.Purpose!=purpose||!StringComparer.OrdinalIgnoreCase.Equals(record.CandidateSha256Digest,candidate)||!StringComparer.OrdinalIgnoreCase.Equals(record.SecurityReportSha256Digest,securityDigest)||!StringComparer.OrdinalIgnoreCase.Equals(record.ResultSha256Digest,resultDigest)||!StringComparer.OrdinalIgnoreCase.Equals(r.GetString(1),digest)||r.GetString(2)!=$"evidence://sandbox/{id:D}/sha256/{digest}"||!record.Result.IsAccepted)throw new InvalidOperationException("Sandbox evidence binding invalid.");var ev=record.EvidenceReferences.Concat(r.GetFieldValue<string[]>(3)).Append(r.GetString(2)).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToImmutableArray();return new(id,security,generation,run,tenant,GovernedIntentPolicyOutcome.Permit,true,false,false,candidate,securityDigest,record.SandboxImage,record.Result.ExitCode,record.Result.TimedOut,record.Result.IsolationViolationDetected,record.Result.ProducedArtifactReferences,resultDigest,r.GetString(2),ev,"Separately approved Tests",new(r.GetDateTime(4).ToUniversalTime()));}catch(NpgsqlException){throw new TestsDependencyUnavailableException("Sandbox evidence unavailable.");}}
}

public sealed class PostgreSqlTestsSecurityReader(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):ITestsSecurityValidationReceiptReader
{
    public async Task<GovernedSecurityValidationReceipt?> LoadAsync(Guid id,string tenant,string purpose,Guid sandbox,string sandboxEvidence,Guid generation,Guid run,string candidate,string report,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new TestsDependencyUnavailableException("Security evidence not configured.");const string sql="SELECT s.record_json,s.record_sha256_digest,s.evidence_reference,s.evidence_references,s.recorded_at FROM software_factory.security_validation_evidence s JOIN software_factory.sandbox_evidence x ON x.tenant_id=s.tenant_id AND x.security_validation_id=s.validation_id WHERE s.tenant_id=@tenant AND s.validation_id=@id AND x.execution_id=@sandbox AND x.evidence_reference=@sandbox_evidence AND s.generation_id=@generation AND s.delivery_run_id=@run AND s.candidate_sha256_digest=@candidate AND s.security_report_sha256_digest=@report";await using var cn=await data.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand(sql,cn){CommandTimeout=o.CommandTimeoutSeconds};foreach(var x in new[]{("tenant",NpgsqlDbType.Text,(object)tenant),("id",NpgsqlDbType.Uuid,id),("sandbox",NpgsqlDbType.Uuid,sandbox),("sandbox_evidence",NpgsqlDbType.Text,sandboxEvidence),("generation",NpgsqlDbType.Uuid,generation),("run",NpgsqlDbType.Uuid,run),("candidate",NpgsqlDbType.Text,candidate),("report",NpgsqlDbType.Text,report)})TestsDb.Add(cmd,x.Item1,x.Item2,x.Item3);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;var record=JsonSerializer.Deserialize<SecurityValidationEvidenceRecord>(r.GetString(0))??throw new InvalidOperationException();var digest=TestsDb.Digest(record);if(record.Purpose!=purpose||!record.Report.IsAccepted||record.Report.Gate!=Validation.ValidationGate.Security||!StringComparer.OrdinalIgnoreCase.Equals(r.GetString(1),digest))throw new InvalidOperationException("Security evidence binding invalid.");var ev=record.EvidenceReferences.Concat(r.GetFieldValue<string[]>(3)).Append(r.GetString(2)).Distinct(StringComparer.Ordinal).ToImmutableArray();return new(id,record.StaticValidationId,generation,run,tenant,GovernedIntentPolicyOutcome.Permit,Validation.ValidationGate.Security,true,false,false,candidate,record.StaticReportSha256Digest,report,record.Report.ControlReports,r.GetString(2),ev,"Separately approved Sandbox",new(r.GetDateTime(4).ToUniversalTime()));}
}

public sealed class PostgreSqlTestsCandidateReader(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):ITestsCodeGenerationCandidateReader
{
    public async Task<AuthorizedCodeGenerationCandidateSnapshot?> LoadAsync(Guid id,string tenant,string purpose,Guid sandbox,string sandboxEvidence,string candidate,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new TestsDependencyUnavailableException("Candidate evidence not configured.");const string sql="SELECT g.record_json,g.record_sha256_digest,g.evidence_reference,g.evidence_references,g.recorded_at FROM software_factory.code_generation_evidence g JOIN software_factory.sandbox_evidence x ON x.tenant_id=g.tenant_id AND x.generation_id=g.generation_id WHERE g.tenant_id=@tenant AND g.generation_id=@id AND g.candidate_sha256_digest=@candidate AND x.execution_id=@sandbox AND x.evidence_reference=@sandbox_evidence";await using var cn=await data.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand(sql,cn){CommandTimeout=o.CommandTimeoutSeconds};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,tenant);TestsDb.Add(cmd,"id",NpgsqlDbType.Uuid,id);TestsDb.Add(cmd,"candidate",NpgsqlDbType.Text,candidate);TestsDb.Add(cmd,"sandbox",NpgsqlDbType.Uuid,sandbox);TestsDb.Add(cmd,"sandbox_evidence",NpgsqlDbType.Text,sandboxEvidence);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;var record=JsonSerializer.Deserialize<CodeGenerationEvidenceRecord>(r.GetString(0))??throw new InvalidOperationException();record.Candidate.Validate();if(record.Purpose!=purpose||!record.Evaluation.IsAccepted||!StringComparer.OrdinalIgnoreCase.Equals(r.GetString(1),TestsDb.Digest(record)))throw new InvalidOperationException("Candidate binding invalid.");foreach(var path in record.Candidate.GeneratedFilePaths)GovernedGeneratedPath.Validate(path);var ev=record.EvidenceReferences.Concat(r.GetFieldValue<string[]>(3)).ToImmutableArray();return new(new(id,record.PlanningId,record.PackageSelectionId,record.DeliveryRunId,tenant,GovernedIntentPolicyOutcome.Permit,true,false,false,false,candidate,record.Candidate.Content,record.Candidate.GeneratedFilePaths,record.Evaluation.Findings,r.GetString(2),ev,"Separately approved Static Validation",new(r.GetDateTime(4).ToUniversalTime())),record.Candidate);}
}

public sealed class PostgreSqlTestsRunReader(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):ITestsDeliveryRunReader
{
    public async Task<SoftwareDeliveryRun?> LoadAsync(Guid id,string tenant,string purpose,Guid sandbox,Guid generation,string candidate,string result,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new TestsDependencyUnavailableException("Tests run not configured.");const string sql="SELECT record_json,record_sha256_digest,evidence_reference,recorded_at FROM software_factory.tests_delivery_run_snapshots WHERE tenant_id=@tenant AND run_id=@id AND purpose=@purpose AND sandbox_execution_id=@sandbox AND generation_id=@generation AND candidate_sha256_digest=@candidate AND sandbox_result_sha256_digest=@result";await using var cn=await data.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand(sql,cn){CommandTimeout=o.CommandTimeoutSeconds};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,tenant);TestsDb.Add(cmd,"id",NpgsqlDbType.Uuid,id);TestsDb.Add(cmd,"purpose",NpgsqlDbType.Text,purpose);TestsDb.Add(cmd,"sandbox",NpgsqlDbType.Uuid,sandbox);TestsDb.Add(cmd,"generation",NpgsqlDbType.Uuid,generation);TestsDb.Add(cmd,"candidate",NpgsqlDbType.Text,candidate);TestsDb.Add(cmd,"result",NpgsqlDbType.Text,result);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;var run=JsonSerializer.Deserialize<SoftwareDeliveryRun>(r.GetString(0))??throw new InvalidOperationException();run.Validate();if(run.CurrentStage!=DeliveryStage.Sandbox||!StringComparer.OrdinalIgnoreCase.Equals(r.GetString(1),TestsDb.Digest(run))||r.GetString(2)!=$"evidence://delivery-runs/{id:D}/sha256/{TestsDb.Digest(run)}")throw new InvalidOperationException("Tests run binding invalid.");return run;}
}

public sealed class PostgreSqlTestManifestReader(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):IGovernedTestManifestReader
{
    public async Task<GovernedTestManifest?> LoadAsync(string reference,string tenant,string purpose,string expected,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new TestsDependencyUnavailableException("Manifest catalog not configured.");const string sql="SELECT record_json,record_sha256_digest,evidence_reference FROM software_factory.governed_test_manifests WHERE tenant_id=@tenant AND manifest_reference=@reference AND purpose=@purpose AND manifest_sha256_digest=@digest";await using var cn=await data.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand(sql,cn){CommandTimeout=o.CommandTimeoutSeconds};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,tenant);TestsDb.Add(cmd,"reference",NpgsqlDbType.Text,reference);TestsDb.Add(cmd,"purpose",NpgsqlDbType.Text,purpose);TestsDb.Add(cmd,"digest",NpgsqlDbType.Text,expected);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;var m=JsonSerializer.Deserialize<GovernedTestManifest>(r.GetString(0))??throw new InvalidOperationException();m.Validate();if(!StringComparer.OrdinalIgnoreCase.Equals(r.GetString(1),TestsDb.Digest(m))||!r.GetString(2).StartsWith("evidence://tests/manifests/",StringComparison.Ordinal))throw new InvalidOperationException("Manifest binding invalid.");return m;}
}

public sealed class PostgreSqlTestsEvidenceRecorder(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):ITestsEvidenceRecorder
{
    private const string SelectSql="SELECT delivery_run_id,result_sha256_digest,record_sha256_digest,evidence_reference,recorded_at FROM software_factory.tests_evidence WHERE tenant_id=@tenant AND execution_id=@id FOR UPDATE";
    private const string InsertSql="INSERT INTO software_factory.tests_evidence(tenant_id,execution_id,sandbox_execution_id,security_validation_id,generation_id,delivery_run_id,candidate_sha256_digest,security_report_sha256_digest,sandbox_result_sha256_digest,test_manifest_sha256_digest,result_sha256_digest,record_sha256_digest,record_json,evidence_reference,evidence_references,recorded_at) VALUES(@tenant,@id,@sandbox,@security,@generation,@run,@candidate,@security_digest,@sandbox_digest,@manifest,@result,@record_digest,@json,@evidence,@references,@at) ON CONFLICT DO NOTHING";
    public async Task<TestsEvidenceReceipt> RecordAsync(TestsEvidenceRecord record,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new TestsDependencyUnavailableException("Tests evidence not configured.");var json=JsonSerializer.Serialize(record);var digest=TestsDb.Digest(record);var evidence=$"evidence://tests/{record.ExecutionId:D}/sha256/{digest}";try{await using var cn=await data.OpenConnectionAsync(ct);await using var tx=await cn.BeginTransactionAsync(IsolationLevel.ReadCommitted,ct);var existing=await LoadAsync(cn,tx,record.TenantId,record.ExecutionId,o.CommandTimeoutSeconds,ct);if(existing is not null){ValidateExisting(record,digest,existing);await tx.CommitAsync(ct);return existing.Receipt;}await using var cmd=new NpgsqlCommand(InsertSql,cn,tx){CommandTimeout=o.CommandTimeoutSeconds};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,record.TenantId);TestsDb.Add(cmd,"id",NpgsqlDbType.Uuid,record.ExecutionId);TestsDb.Add(cmd,"sandbox",NpgsqlDbType.Uuid,record.SandboxExecutionId);TestsDb.Add(cmd,"security",NpgsqlDbType.Uuid,record.SecurityValidationId);TestsDb.Add(cmd,"generation",NpgsqlDbType.Uuid,record.GenerationId);TestsDb.Add(cmd,"run",NpgsqlDbType.Uuid,record.DeliveryRunId);TestsDb.Add(cmd,"candidate",NpgsqlDbType.Text,record.CandidateSha256Digest);TestsDb.Add(cmd,"security_digest",NpgsqlDbType.Text,record.SecurityReportSha256Digest);TestsDb.Add(cmd,"sandbox_digest",NpgsqlDbType.Text,record.SandboxResultSha256Digest);TestsDb.Add(cmd,"manifest",NpgsqlDbType.Text,record.TestManifestSha256Digest);TestsDb.Add(cmd,"result",NpgsqlDbType.Text,record.ResultSha256Digest);TestsDb.Add(cmd,"record_digest",NpgsqlDbType.Text,digest);TestsDb.Add(cmd,"json",NpgsqlDbType.Jsonb,json);TestsDb.Add(cmd,"evidence",NpgsqlDbType.Text,evidence);TestsDb.Add(cmd,"references",NpgsqlDbType.Array|NpgsqlDbType.Text,record.EvidenceReferences.ToArray());TestsDb.Add(cmd,"at",NpgsqlDbType.TimestampTz,record.ExecutedAt);if(await cmd.ExecuteNonQueryAsync(ct)==0){existing=await LoadAsync(cn,tx,record.TenantId,record.ExecutionId,o.CommandTimeoutSeconds,ct)??throw new InvalidOperationException("Tests evidence conflicted outside its tenant identity.");ValidateExisting(record,digest,existing);await tx.CommitAsync(ct);return existing.Receipt;}await tx.CommitAsync(ct);return new(record.ExecutionId,record.DeliveryRunId,record.TenantId,record.ResultSha256Digest,evidence,record.ExecutedAt);}catch(NpgsqlException){throw new TestsDependencyUnavailableException("Tests evidence unavailable.");}}
    private static async Task<Stored?> LoadAsync(NpgsqlConnection cn,NpgsqlTransaction tx,string tenant,Guid id,int timeout,CancellationToken ct){await using var cmd=new NpgsqlCommand(SelectSql,cn,tx){CommandTimeout=timeout};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,tenant);TestsDb.Add(cmd,"id",NpgsqlDbType.Uuid,id);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;return new(new(id,r.GetGuid(0),tenant,r.GetString(1),r.GetString(3),new(r.GetDateTime(4).ToUniversalTime())),r.GetString(2));}
    private static void ValidateExisting(TestsEvidenceRecord record,string digest,Stored stored){if(stored.Receipt.DeliveryRunId!=record.DeliveryRunId||!StringComparer.OrdinalIgnoreCase.Equals(stored.Receipt.ResultSha256Digest,record.ResultSha256Digest)||!StringComparer.OrdinalIgnoreCase.Equals(stored.RecordDigest,digest)||stored.Receipt.EvidenceReference!=$"evidence://tests/{record.ExecutionId:D}/sha256/{digest}")throw new InvalidOperationException("Stored Tests evidence does not match the authorized record.");}
    private sealed record Stored(TestsEvidenceReceipt Receipt,string RecordDigest);
}
